inline const uint8_t *presetMask(uint8_t avatar) {
  const auto *icon = TurnHubAvatars::presetAvatar(avatar);
  if (!icon) return nullptr;
  if (strcmp(icon->key, "bolt") == 0) return MASK_bolt;
  if (strcmp(icon->key, "cat") == 0) return MASK_cat;
  if (strcmp(icon->key, "crown") == 0) return MASK_crown;
  if (strcmp(icon->key, "die") == 0) return MASK_die;
  if (strcmp(icon->key, "flame") == 0) return MASK_flame;
  if (strcmp(icon->key, "gem") == 0) return MASK_gem;
  if (strcmp(icon->key, "moon") == 0) return MASK_moon;
  if (strcmp(icon->key, "shield") == 0) return MASK_shield;
  if (strcmp(icon->key, "skull") == 0) return MASK_skull;
  if (strcmp(icon->key, "star") == 0) return MASK_star;
  if (strcmp(icon->key, "sword") == 0) return MASK_sword;
  if (strcmp(icon->key, "tree") == 0) return MASK_tree;
  return nullptr;
}
